from pathlib import Path

# 1) Client list: keep the reference structure, without profile photos.
p=Path('coach-premium-core-v9.js')
s=p.read_text()
a=s.index('  function clientCard(c){')
b=s.index('  function renderClients(){',a)
new_card=r'''  function clientCard(c){
    const goal=c.goal||c.objective||c.objetivo||'Objetivo por definir';
    const weight=c.weight||c.peso||'';
    const fat=c.body_fat??c.bodyFat??c.fat??c.grasa??'';
    return `<article class="dcc-cl-card dcc-cl-card-ref" data-name="${esc(c.name).toLowerCase()}" data-pending="${pendingCheck(c)?'1':'0'}" onclick="openClient('${esc(c.id)}')"><div class="dcc-cl-info"><div class="dcc-cl-name">${esc(c.name)}</div><div class="dcc-cl-goal">${esc(goal)}</div><div class="dcc-cl-ref-meta">${weight?`<span>▣ &nbsp;${esc(weight)} kg</span>`:''}${fat!==''?`<span>◌ &nbsp;${esc(fat)} %</span>`:''}</div></div><span class="dcc-cl-active">Activo</span><span class="dcc-cl-chevron">›</span></article>`;
  }
'''
s=s[:a]+new_card+s[b:]
# Add compact reference-list CSS to the existing stylesheet.
needle='      .dcc-cl-empty{padding:24px;text-align:center;color:#929aa5}\n'
extra=r'''      .dcc-cl-card-ref{grid-template-columns:minmax(0,1fr) auto 18px!important;cursor:pointer!important;min-height:96px!important;padding:16px 18px!important}
      .dcc-cl-card-ref .dcc-cl-training,.dcc-cl-card-ref .dcc-cl-manage{display:none!important}
      .dcc-cl-ref-meta{display:flex;gap:15px;align-items:center;margin-top:9px;color:#8d96a1;font-size:10px;font-weight:650}
      .dcc-cl-active{align-self:center;padding:7px 11px;border-radius:999px;background:rgba(57,185,130,.13);color:#47b987;font-size:9px;font-weight:850}
      .dcc-cl-chevron{align-self:center;color:#d9aa4a;font-size:27px;line-height:1}
'''
if needle not in s: raise SystemExit('client list css anchor missing')
s=s.replace(needle,needle+extra,1)
p.write_text(s)

# 2) Client profile: reproduce the approved reference hierarchy.
p=Path('client-admin-premium.js')
s=p.read_text()
css_anchor='@media(max-width:520px){#coach-main.dcc-ca'
ref_css=r'''
.dcc-ca-profilebar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:13px 2px 10px}.dcc-ca-profilecopy{min-width:0}.dcc-ca-profilecopy h1{margin:0;font-size:28px;letter-spacing:-.8px}.dcc-ca-status{display:flex;align-items:center;gap:6px;margin-top:4px;color:#8f98a3;font-size:10px}.dcc-ca-status:before{content:'';width:7px;height:7px;border-radius:50%;background:#39b982;box-shadow:0 0 0 3px rgba(57,185,130,.10)}.dcc-ca-profilegoal{margin-top:3px;color:#b98a34;font-size:10px}.dcc-ca-edit{flex:none;border:1px solid rgba(217,170,74,.55);border-radius:13px;background:linear-gradient(135deg,#f3cf69,#d9a63d);color:#17120a;padding:10px 13px;font-size:10px;font-weight:850}.dcc-ca-metrics-ref{display:grid;grid-template-columns:repeat(3,1fr);margin:8px 0 10px;border:1px solid rgba(217,170,74,.28);border-radius:15px;background:rgba(255,255,255,.018);overflow:hidden}.dcc-ca-mini{padding:10px 8px;text-align:center;border-right:1px solid rgba(217,170,74,.16)}.dcc-ca-mini:last-child{border-right:0}.dcc-ca-mini b{display:block;font-size:14px}.dcc-ca-mini span{display:block;margin-top:3px;color:#8f98a3;font-size:8px}.dcc-ca-tabs{border-radius:15px!important;padding:3px!important}.dcc-ca-tab{border-radius:11px!important;padding:8px 2px!important}.dcc-ca-tab-ico{display:block;margin:0 auto 3px;font-size:15px;line-height:1}.dcc-ca-tab-label{display:block;font-size:8px}.dcc-ca-summary{display:grid;gap:10px}.dcc-ca-evolution{margin-top:0}.dcc-ca-section-head{display:flex;align-items:center;justify-content:space-between;gap:10px}.dcc-ca-section-head h2{margin:0;font-size:17px}.dcc-ca-link{border:0;background:transparent;color:#b98a34;font-size:9px;font-weight:800}.dcc-ca-photo-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:11px}.dcc-ca-photo{min-width:0}.dcc-ca-photo-box{aspect-ratio:4/5;display:grid;place-items:center;border:1px solid rgba(217,170,74,.30);border-radius:12px;background:linear-gradient(145deg,rgba(217,170,74,.06),rgba(255,255,255,.015));color:#a77b2e;font-size:22px}.dcc-ca-photo b{display:block;margin-top:5px;text-align:center;font-size:9px}.dcc-ca-photo small{display:block;margin-top:2px;text-align:center;color:#8f98a3;font-size:7px}.dcc-ca-next-photo{display:flex;align-items:center;gap:9px;margin-top:9px;padding:9px 10px;border:1px solid rgba(217,170,74,.24);border-radius:12px;color:#8f98a3;font-size:9px}.dcc-ca-next-photo b{color:#b98a34}.dcc-ca-data-card .dcc-ca-grid{margin-top:8px}.dcc-ca-summary-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px}.dcc-ca-summary-actions button{min-height:42px;border-radius:13px;font-size:10px;font-weight:850}.dcc-ca-action-primary{border:1px solid #f0c96b;background:linear-gradient(135deg,#f3cf69,#d9a63d);color:#17120a}.dcc-ca-action-secondary{border:1px solid rgba(217,170,74,.42);background:transparent;color:#d7a744}.dcc-ca-danger-row{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:2px}.dcc-ca-danger-row .dcc-ca-delete{margin:0}.dcc-ca-editpane{display:grid;gap:9px}.dcc-ca-editfield label{display:block;margin:0 0 4px;color:#8f98a3;font-size:8px}.dcc-ca-editfield input,.dcc-ca-editfield textarea{width:100%;border:1px solid #343d45;border-radius:11px;background:#0a0f13;color:#f5f3ef;padding:10px 11px;outline:0}.dcc-ca-editfield textarea{min-height:70px;resize:vertical}.dcc-ca-edit-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:4px}.dcc-ca-edit-actions button{padding:11px;border-radius:12px;font-weight:850}.dcc-ca-save{border:1px solid #f0c96b;background:linear-gradient(135deg,#f3cf69,#d9a63d);color:#17120a}.dcc-ca-cancel{border:1px solid #39434c;background:transparent;color:#ddd}
html.dcc-theme-light-premium body #coach #coach-main.dcc-ca .dcc-ca-profilecopy h1,html.dcc-theme-light-premium body #coach #coach-main.dcc-ca .dcc-ca-section-head h2{color:#17191d!important}html.dcc-theme-light-premium body #coach #coach-main.dcc-ca .dcc-ca-metrics-ref,html.dcc-theme-light-premium body #coach #coach-main.dcc-ca .dcc-ca-photo-box{background:#fffefa!important;border-color:rgba(177,119,18,.25)!important}html.dcc-theme-light-premium body #coach #coach-main.dcc-ca .dcc-ca-photo-box{color:#b47d1d!important}html.dcc-theme-light-premium body #coach #coach-main.dcc-ca .dcc-ca-editfield input,html.dcc-theme-light-premium body #coach #coach-main.dcc-ca .dcc-ca-editfield textarea{background:#fffefa!important;color:#17191d!important;border-color:rgba(177,119,18,.25)!important}
'''
if css_anchor not in s: raise SystemExit('client admin css anchor missing')
s=s.replace(css_anchor,ref_css+css_anchor,1)

start=s.index("function render(id,tab='summary')")
end=s.index('window.dccToggleTrainingDay',start)
new_render=r'''function summaryPane(id,cl,m){return `<div class="dcc-ca-summary"><section class="dcc-ca-card dcc-ca-evolution"><div class="dcc-ca-section-head"><h2>Evolución física</h2><button class="dcc-ca-link" onclick="dccOpenClientTab('${id}','progress')">Ver historial ›</button></div><div class="dcc-ca-photo-grid"><div class="dcc-ca-photo"><div class="dcc-ca-photo-box">↶</div><b>Espalda</b><small>Foto mensual</small></div><div class="dcc-ca-photo"><div class="dcc-ca-photo-box">◎</div><b>Frente</b><small>Foto mensual</small></div><div class="dcc-ca-photo"><div class="dcc-ca-photo-box">◐</div><b>Lateral</b><small>Foto mensual</small></div></div><div class="dcc-ca-next-photo"><span>▣</span><span><b>Check-in fotográfico</b><br>3 fotos · espalda, frente y lateral · 1 vez al mes</span></div></section><section class="dcc-ca-card dcc-ca-data-card"><div class="dcc-ca-section-head"><h2>Datos principales</h2><button class="dcc-ca-link" onclick="dccClientEdit('${id}')">✎ Editar</button></div><div class="dcc-ca-grid">${info('Edad',clientAge(cl))}${info('Altura',clientHeight(cl))}${info('Peso actual',m.current.toFixed(1).replace('.',',')+' kg')}${info('% grasa actual',m.fc!=null?m.fc.toFixed(1).replace('.',',')+' %':'—')}${info('Objetivo',esc(cl.goal||'—'))}${info('Último check-in',lastCheckin(id))}${info('Alimentos a evitar',esc(avoidText(cl)||'Sin alimentos indicados'))}</div></section><div class="dcc-ca-summary-actions"><button class="dcc-ca-action-primary" onclick="dccOpenClientTab('${id}','followup')">Seguimiento</button><button class="dcc-ca-action-secondary" onclick="dccOpenClientChat('${id}')">Mensajes</button></div><div class="dcc-ca-danger-row"><button class="dcc-ca-action-secondary" onclick="dccClientEdit('${id}')">Editar cliente</button><button class="dcc-ca-delete" onclick="dccLegacyDelete('${id}')">Eliminar cliente</button></div></div>`}
function editPane(id,cl){return `<section class="dcc-ca-card"><div class="dcc-ca-section-head"><h2>Editar cliente</h2></div><div class="dcc-ca-editpane" style="margin-top:12px"><div class="dcc-ca-editfield"><label>Nombre</label><input id="dccEditName" value="${esc(cl.name||'')}"></div><div class="dcc-ca-editfield"><label>Objetivo</label><input id="dccEditGoal" value="${esc(cl.goal||'')}"></div><div class="dcc-ca-editfield"><label>Edad</label><input id="dccEditAge" inputmode="numeric" value="${esc(cl.age??cl.edad??'')}"></div><div class="dcc-ca-editfield"><label>Altura (cm)</label><input id="dccEditHeight" inputmode="decimal" value="${esc(cl.height_cm??cl.height??cl.altura??'')}"></div><div class="dcc-ca-editfield"><label>Alimentos a evitar</label><textarea id="dccEditAvoid">${esc(avoidText(cl))}</textarea></div><div class="dcc-ca-edit-actions"><button class="dcc-ca-cancel" onclick="dccOpenClientTab('${id}','summary')">Cancelar</button><button class="dcc-ca-save" onclick="dccSaveClientEdit('${id}')">Guardar</button></div></div></section>`}
function render(id,tab='summary'){css();const cl=c(id);if(!cl)return;window.selectedClient=id;const main=document.getElementById('coach-main');if(!main)return;main.className='dcc-ca';const ws=weights(id,cl),initial=ws[0]??0,current=ws.at(-1)??initial,fs=findFatValues(id,cl),fi=fs[0]??null,fc=fs.at(-1)??null;const age=clientAge(cl);main.innerHTML=`<div class="dcc-ca-wrap"><button class="dcc-ca-back" onclick="showCoach('clients')">← Clientes</button><header class="dcc-ca-profilebar"><div class="dcc-ca-profilecopy"><h1>${esc(cl.name)}</h1><div class="dcc-ca-status">Cliente activo</div><div class="dcc-ca-profilegoal">${esc(cl.goal||'Objetivo por definir')}</div></div><button class="dcc-ca-edit" onclick="dccClientEdit('${id}')">Editar cliente</button></header><div class="dcc-ca-metrics-ref"><div class="dcc-ca-mini"><b>${current.toFixed(1).replace('.',',')} kg</b><span>Peso actual</span></div><div class="dcc-ca-mini"><b>${fc!=null?fc.toFixed(1).replace('.',',')+' %':'—'}</b><span>Grasa actual</span></div><div class="dcc-ca-mini"><b>${esc(age)}</b><span>Edad</span></div></div><nav class="dcc-ca-tabs"><button class="dcc-ca-tab ${tab==='summary'?'active':''}" onclick="dccOpenClientTab('${id}','summary')"><span class="dcc-ca-tab-ico">▦</span><span class="dcc-ca-tab-label">Resumen</span></button><button class="dcc-ca-tab ${tab==='food'?'active':''}" onclick="dccOpenClientTab('${id}','food')"><span class="dcc-ca-tab-ico">♨</span><span class="dcc-ca-tab-label">Dieta</span></button><button class="dcc-ca-tab ${tab==='training'?'active':''}" onclick="dccOpenClientTab('${id}','training')"><span class="dcc-ca-tab-ico">⌁</span><span class="dcc-ca-tab-label">Rutina</span></button><button class="dcc-ca-tab ${tab==='progress'?'active':''}" onclick="dccOpenClientTab('${id}','progress')"><span class="dcc-ca-tab-ico">↗</span><span class="dcc-ca-tab-label">Progreso</span></button><button class="dcc-ca-tab ${tab==='followup'?'active':''}" onclick="dccOpenClientTab('${id}','followup')"><span class="dcc-ca-tab-ico">▣</span><span class="dcc-ca-tab-label">Seguimiento</span></button></nav><div>${pane(id,tab,cl,{initial,current,fi,fc})}</div></div>`}
function pane(id,t,cl,m){if(t==='food')return foodPane(id);if(t==='training')return trainingPane(id);if(t==='progress')return`<section class="dcc-ca-card"><div class="dcc-ca-title"><h2>Progreso</h2></div><div class="dcc-ca-grid">${info('Peso inicial',m.initial.toFixed(1).replace('.',',')+' kg')}${info('Peso actual',m.current.toFixed(1).replace('.',',')+' kg')}${info('Grasa inicial',m.fi!=null?m.fi.toFixed(1).replace('.',',')+' %':'—')}${info('Grasa actual',m.fc!=null?m.fc.toFixed(1).replace('.',',')+' %':'—')}</div></section>`;if(t==='followup')return followupPane(id);if(t==='edit')return editPane(id,cl);return summaryPane(id,cl,m)}
window.dccOpenClientTab=(id,tab)=>{if(tab==='training')window.__dccTrainingOpen=null;render(id,tab)};
window.dccClientEdit=id=>render(id,'edit');
window.dccSaveClientEdit=async id=>{const cl=c(id);if(!cl)return;const name=document.getElementById('dccEditName')?.value.trim(),goal=document.getElementById('dccEditGoal')?.value.trim(),age=document.getElementById('dccEditAge')?.value.trim(),height=document.getElementById('dccEditHeight')?.value.trim(),avoid=document.getElementById('dccEditAvoid')?.value.trim();if(name)cl.name=name;cl.goal=goal;if('age'in cl||!('edad'in cl))cl.age=age;else cl.edad=age;if('height_cm'in cl||(!('height'in cl)&&!('altura'in cl)))cl.height_cm=height;else if('height'in cl)cl.height=height;else cl.altura=height;if('foods_to_avoid'in cl||!('foodsToAvoid'in cl))cl.foods_to_avoid=avoid;else cl.foodsToAvoid=avoid;if(typeof saveData==='function')saveData();try{if(window.supabaseClient){const payload={name:cl.name,goal:cl.goal};if('age'in cl)payload.age=cl.age;if('height_cm'in cl)payload.height_cm=cl.height_cm;if('foods_to_avoid'in cl)payload.foods_to_avoid=cl.foods_to_avoid;const {error}=await supabaseClient.from('clients').update(payload).eq('id',id);if(error)throw error}if(typeof toast==='function')toast('Cliente actualizado')}catch(e){console.error('No se pudo actualizar el cliente:',e);if(typeof toast==='function')toast('Cambios guardados en la app; revisa la conexión')}render(id,'summary')};
'''
s=s[:start]+new_render+s[end:]
p.write_text(s)
